# Read-only AST comparison of two already identified source files.
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
if($env:GITHUB_ACTIONS -eq 'true' -or -not [Environment]::UserInteractive){throw 'OWNER_CONTEXT_REQUIRED'}
$spool=Join-Path $env:ProgramData 'TorrentTVVietsub\LaptopHostOps'
$rq=Get-Content -LiteralPath (Join-Path $spool 'Requests\request.json') -Raw | ConvertFrom-Json
$base=Join-Path $env:LOCALAPPDATA 'TorrentTVVietsub'
$report=Join-Path $base ('NativeBrowserTest\v13-ast-'+$rq.nonce)
New-Item -ItemType Directory -Path $report -ErrorAction Stop|Out-Null
$py=@'
import ast,hashlib,json,pathlib,sys
base,report=map(pathlib.Path,sys.argv[1:3])
expected={"poc/p2-aisub/run_assumed_source_gateway.py":"\"\"\"Explicit PC-only prototype entrypoint: EN source -> CLI provider -> paired TV.\n\nDOES NOT execute on import or in GitHub CI. No source discovery, no\nTorrServer/admin operations, no Windows service/firewall/UPnP modifications.\nOne permitted PC LAN interface, one pre-supplied timed SRT/VTT and media key.\n\nPC only serves HTTPS with an explicit certificate/key outside the repository.\nThe TV must pin the PC leaf certificate's SHA256 and verify its IP-SAN.\nNo listener starts without --start-lan, --tls-cert and --tls-key.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport threading\n\nfrom assumed_source_handoff import (\n    AssumedEnglishSubtitle,\n)\nfrom lean120_api import load_profile\nfrom automatic_lean120_worker import AutomaticLean120Worker\nfrom verified_source_manifest import verified_source_from_manifest\nfrom paired_activation import PairedActivation, create_paired_server\nfrom p4_tls import certificate_fingerprint_sha256, create_tls_context\nfrom synthetic_mock_feed import (\n    publish_synthetic_revisions, synthetic_source_srt,\n)\n\nHEX_32 = re.compile(r\"[0-9a-fA-F]{64}\\Z\")\n\n\ndef build_controller(\n    *, media_key: str, source_file: Path | None, master_hex: str,\n    execute_provider: bool, profile_file: Path,\n    glossary: dict[str,str] | None = None,\n    mock_revisions: bool = False,\n    mock_single_paired_media: bool = False,\n    auto_state_dir: Path | None = None,\n    source_manifest: Path | None = None,\n) -> PairedActivation:\n    if not isinstance(master_hex,str) or not HEX_32.fullmatch(master_hex):\n        raise ValueError(\"P4_DEVICE_PAIRING_KEY_REQUIRED\")\n    if mock_revisions and execute_provider:\n        raise ValueError(\"P4_MOCK_CANNOT_CALL_PROVIDER\")\n    if mock_single_paired_media and (\n        not mock_revisions or media_key is not None or\n        source_file is not None or execute_provider\n    ):\n        raise ValueError(\"P4_MOCK_SINGLE_PAIRED_MEDIA_SCOPE_INVALID\")\n    if source_manifest is not None:\n        if (not execute_provider or mock_revisions or mock_single_paired_media or\n            media_key is not None or source_file is not None or\n            not source_manifest.is_absolute() or\n            not source_manifest.is_file() or source_manifest.is_symlink()):\n            raise ValueError(\"P2_OWNER_SOURCE_MANIFEST_SCOPE_INVALID\")\n        source = None\n    elif mock_revisions:\n        if source_file is not None:\n            raise ValueError(\"P4_MOCK_REJECTS_REAL_SOURCE_FILE\")\n        source=(None if mock_single_paired_media else\n            AssumedEnglishSubtitle.from_supplied(\n                media_key=media_key,fmt=\"srt\",source_bytes=synthetic_source_srt()))\n    else:\n        if (source_file is None or not source_file.is_file() or\n                source_file.suffix.lower() not in (\".srt\",\".vtt\")):\n            raise ValueError(\"P4_TIMED_SOURCE_FILE_REQUIRED\")\n        source=AssumedEnglishSubtitle.from_supplied(\n            media_key=media_key,fmt=source_file.suffix.lower()[1:],\n            source_bytes=source_file.read_bytes())\n    profile=load_profile(profile_file)\n    if execute_provider and auto_state_dir is None:\n        raise ValueError(\"P2_AUTO_PRIVATE_STATE_DIR_REQUIRED\")\n    # The user-supplied file is assumed to be a correct English match.\n    # No finder/ASR or semantic match claim from this function.\n    if glossary is None:glossary={}\n    def on_activate(feed,handoff):\n        if mock_revisions:\n            def run_mock():\n                try:\n                    publish_synthetic_revisions(handoff.media_key,feed)\n                    print(\"P4_SYNTHETIC_120_240_PUBLISHED_NOT_REAL_TV_PASS\")\n                except Exception:\n                    print(\"P4_SYNTHETIC_PUBLISH_FAILED\")\n            threading.Thread(target=run_mock,daemon=True,\n                             name=\"p4-synthetic-feed\").start()\n            return\n        if not execute_provider:\n            # Local activation dry-run; no provider call and no fake captions.\n            return\n        def run():\n            try:\n                worker = AutomaticLean120Worker(\n                    state_root=auto_state_dir, profile=profile,\n                    glossary=glossary)\n                final = worker.run(handoff, on_revision=feed.publish)\n                print(\"P2_AUTO_LEAN120_COMPLETE_PRIVATE_VI_FILE=true\")\n                print(\"P2_AUTO_LEAN120_CUE_COUNT=\"+str(final.translated_count))\n                print(\"P4_LAN_PUBLISHED_NOT_REAL_TV_PASS=true\")\n            except Exception:\n                # Never include provider replies, API keys, subtitle text.\n                print(\"P2_AUTO_LEAN120_STOP_PRIVATE_OWNER_REVIEW_REQUIRED\")\n        threading.Thread(target=run,daemon=True,name=\"p4-lean120\").start()\n    if mock_single_paired_media:\n        def authenticated_fixture(media: str) -> AssumedEnglishSubtitle:\n            return AssumedEnglishSubtitle.from_supplied(\n                media_key=media,fmt=\"srt\",source_bytes=synthetic_source_srt())\n        return PairedActivation(\n            device_secret=bytes.fromhex(master_hex),supplied={},\n            on_activate=on_activate,\n            authenticated_mock_source_factory=authenticated_fixture)\n    if source_manifest is not None:\n        return PairedActivation(\n            device_secret=bytes.fromhex(master_hex), supplied={},\n            on_activate=on_activate,\n            authenticated_source_factory=lambda media: verified_source_from_manifest(\n                source_manifest, media))\n    return PairedActivation(\n        device_secret=bytes.fromhex(master_hex),\n        supplied={media_key:source},on_activate=on_activate)\n\n\ndef main() -> int:\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--bind\",required=True,help=\"Explicit RFC1918 IPv4 PC LAN interface\")\n    parser.add_argument(\"--port\",required=True,type=int)\n    parser.add_argument(\"--media-key\",\n                        help=\"Required for real/source-supplied mode; omitted only in paired mock mode\")\n    parser.add_argument(\"--source\",type=Path,\n                        help=\"PRE-SUPPLIED and authorized EN SRT/VTT (not in mock mode)\")\n    parser.add_argument(\"--source-manifest\",type=Path,\n                        help=\"Owner-private verified EN source registry; exact TV media lookup AFTER HMAC\")\n    parser.add_argument(\"--mock-revisions\",action=\"store_true\",\n                        help=\"Dev-only synthetic 120\u2192240; no source file or model call\")\n    parser.add_argument(\"--mock-single-paired-media\",action=\"store_true\",\n                        help=\"Dev only: auto-bind one correctly HMAC-authenticated TV media, no manual key\")\n    parser.add_argument(\"--profile\",type=Path,\n        default=Path(__file__).with_name(\"translator_profile.json\"))\n    parser.add_argument(\"--glossary-json\",type=Path)\n    parser.add_argument(\"--execute-provider\",action=\"store_true\")\n    parser.add_argument(\"--auto-state-dir\",type=Path,\n        help=\"Required with --execute-provider: private owner-only durable LEAN120 checkpoints\")\n    parser.add_argument(\"--start-lan\",action=\"store_true\")\n    parser.add_argument(\"--tls-cert\",type=Path,\n                        help=\"Explicit owner-generated PEM with IP-SAN for --bind\")\n    parser.add_argument(\"--tls-key\",type=Path,\n                        help=\"Matching owner-held private key outside repository\")\n    args=parser.parse_args()\n    if args.execute_provider and (\n        os.environ.get(\"GITHUB_ACTIONS\", \"\").lower() == \"true\" or\n        os.environ.get(\"CI\", \"\").lower() == \"true\"\n    ):\n        parser.error(\"P2_AUTO_LIVE_PROVIDER_IN_CI_FORBIDDEN\")\n    if not args.start_lan:\n        parser.error(\"EXPLICIT_START_LAN_REQUIRED\")\n    if args.tls_cert is None or args.tls_key is None:\n        parser.error(\"P4_TLS_CERT_AND_KEY_REQUIRED\")\n    key=os.environ.get(\"P4_PAIRING_MASTER_HEX\",\"\")\n    glossary=(json.loads(args.glossary_json.read_text(encoding=\"utf-8\"))\n              if args.glossary_json else {})\n    controller=build_controller(\n        media_key=args.media_key,source_file=args.source,\n        master_hex=key,execute_provider=args.execute_provider,\n        profile_file=args.profile,glossary=glossary,\n        mock_revisions=args.mock_revisions,\n        mock_single_paired_media=args.mock_single_paired_media,\n        auto_state_dir=args.auto_state_dir,\n        source_manifest=args.source_manifest)\n    tls_context=create_tls_context(args.tls_cert,args.tls_key)\n    fingerprint=certificate_fingerprint_sha256(args.tls_cert)\n    server=create_paired_server(\n        controller,host=args.bind,port=args.port,tls_context=tls_context)\n    print(\"P4_TLS_CERT_SHA256=\"+fingerprint)\n    print(\"P4_PC_PAIRED_GATEWAY_START_EXPLICIT_TLS_LAN_ONLY\")\n    try:server.serve_forever(poll_interval=0.5)\n    except KeyboardInterrupt:pass\n    finally:server.server_close()\n    return 0\n\n\nif __name__==\"__main__\":\n    raise SystemExit(main())\n","poc/p3-vietsub-trigger/activation_gate.py":"\"\"\"P3-TRIGGER source-only playback activation gate.\n\nA deterministic policy layer between an ALREADY authenticated OMP TV playback\nselection and Draft #140 AutomaticVietsubFlow.selected_media(video_name).\n\nThis is NOT a TV event subscriber, host service, credential provider, network\nclient, D3 media-binding attestation or P4 receiver. Its 'attested' argument\nis a caller-provided assertion, never cryptographic verification by itself.\nIt does not call OpenSubtitles/Gemini or any network/file APIs.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nimport re\n\n_TRIGGER_EVENTS = frozenset({\"PLAY_REQUEST_ACCEPTED\", \"NEXT_QUEUE_ITEM_ACCEPTED\"})\n_HASH = re.compile(r\"(?:[0-9a-f]{40}|[0-9a-f]{64})\", re.ASCII)\n_OPAQUE = re.compile(r\"[A-Za-z0-9_-]{1,128}\", re.ASCII)\n\n\n@dataclass(frozen=True)\nclass PlaybackSelected:\n    # All values must originate from the same authenticated, current TV\n    # PlayRequest + selected QueueItem and an attested TorrServer metadata read.\n    kind: str\n    attested: bool\n    active: bool\n    server_id: str\n    tv_session_id: str\n    torrent_hash: str\n    file_index: int\n    video_name: str\n    owner_auto_enabled: bool\n    subtitle_choice: str  # ON | REQUESTED | OFF | OTHER\n    media_rights_approved: bool\n    local_vi_state: str  # PRESENT | ABSENT | UNKNOWN\n\n\n@dataclass(frozen=True)\nclass TriggerDecision:\n    status: str  # DISPATCH | SKIP | HOLD | WAIT\n    reason: str\n    # Local correlation only; never valid as a D3/P4 authenticated media key.\n    local_fingerprint: str | None = None\n\n\ndef evaluate_playback(event: PlaybackSelected) -> TriggerDecision:\n    \"\"\"A PLAY selection, not a library-add or pause/seek, is authoritative.\n\n    This pure decision *cannot verify* TV pairing/HMAC, server ownership or\n    media bytes. All those checks belong to the trusted runtime adapter.\n    \"\"\"\n    if not isinstance(event, PlaybackSelected):\n        return TriggerDecision(\"HOLD\", \"MALFORMED_EVENT\")\n    if event.kind not in _TRIGGER_EVENTS:\n        return TriggerDecision(\"SKIP\", \"NOT_A_PLAYBACK_SELECTION\")\n    if event.attested is not True or event.active is not True:\n        return TriggerDecision(\"HOLD\", \"UNATTESTED_OR_STALE_SELECTION\")\n    if (not isinstance(event.server_id, str)\n            or _OPAQUE.fullmatch(event.server_id) is None\n            or not isinstance(event.tv_session_id, str)\n            or _OPAQUE.fullmatch(event.tv_session_id) is None\n            or not isinstance(event.torrent_hash, str)\n            or _HASH.fullmatch(event.torrent_hash.lower()) is None\n            or type(event.file_index) is not int or event.file_index < 0\n            or not isinstance(event.video_name, str)\n            or len(event.video_name) > 255 or not event.video_name.strip()\n            or \"/\" in event.video_name or \"\\\\\" in event.video_name\n            or any(ord(ch) < 32 or ord(ch) == 127 for ch in event.video_name)):\n        return TriggerDecision(\"HOLD\", \"MEDIA_IDENTITY_UNVERIFIED\")\n    if event.owner_auto_enabled is not True:\n        return TriggerDecision(\"SKIP\", \"OWNER_AUTO_DISABLED\")\n    if event.subtitle_choice not in (\"ON\", \"REQUESTED\", \"OFF\", \"OTHER\"):\n        return TriggerDecision(\"HOLD\", \"SUBTITLE_CHOICE_UNKNOWN\")\n    if event.subtitle_choice not in (\"ON\", \"REQUESTED\"):\n        return TriggerDecision(\"SKIP\", \"VIEWER_OFF_OR_OTHER\")\n    if event.media_rights_approved is not True:\n        return TriggerDecision(\"HOLD\", \"MEDIA_POLICY_NOT_APPROVED\")\n    if event.local_vi_state == \"UNKNOWN\":\n        return TriggerDecision(\"WAIT\", \"CHECK_LOCAL_VI_TRACKS\")\n    if event.local_vi_state == \"PRESENT\":\n        return TriggerDecision(\"SKIP\", \"REUSE_EXISTING_VI\")\n    if event.local_vi_state != \"ABSENT\":\n        return TriggerDecision(\"HOLD\", \"VI_TRACK_STATUS_INVALID\")\n    # Correlation key includes server+infohash+exact selected file. Deliberately\n    # NOT derived solely from filename as in Draft #140's local cache index.\n    parts = (\n        event.server_id,\n        event.torrent_hash.lower(),\n        str(event.file_index),\n    )\n    fingerprint = sha256(\"\\x00\".join(parts).encode(\"utf-8\")).hexdigest()\n    return TriggerDecision(\"DISPATCH\", \"AGY_FIND_EN_AND_TRANSLATE\", fingerprint)\n\n\nclass ActivationDeduplicator:\n    \"\"\"One in-process last-seen event token; no second worker/queue/cache.\n\n    After a process restart, Draft #140's persistent source+LEAN120 checkpoints\n    remain the authoritative protection against duplicate provider/model calls.\n    \"\"\"\n    def __init__(self) -> None:\n        self._last: tuple[str, str] | None = None\n\n    def consider(self, event: PlaybackSelected) -> TriggerDecision:\n        decision = evaluate_playback(event)\n        if decision.status != \"DISPATCH\":\n            # A different selected item may have VI already, be waiting for\n            # track inventory, or have viewer OFF. It still breaks the active\n            # A->B->A sequence even though B never needed a provider call.\n            # Never let stale/untrusted/non-playback noise reset this guard.\n            if (event.kind in _TRIGGER_EVENTS\n                    and event.attested is True and event.active is True\n                    and decision.reason in (\n                        \"REUSE_EXISTING_VI\", \"CHECK_LOCAL_VI_TRACKS\",\n                        \"VIEWER_OFF_OR_OTHER\", \"OWNER_AUTO_DISABLED\")):\n                self._last = None\n            return decision\n        token = (event.tv_session_id, decision.local_fingerprint or \"\")\n        if token == self._last:\n            return TriggerDecision(\"SKIP\", \"DUPLICATE_CURRENT_PLAY_EVENT\",\n                                   decision.local_fingerprint)\n        self._last = token\n        return decision\n\n    def on_session_closed(self) -> None:\n        self._last = None\n"}
def stripped(tree):
    for node in ast.walk(tree):
        if isinstance(node,(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)) and node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):
            node.body.pop(0)
    return ast.dump(tree,include_attributes=False)
result={}
for rel,src in expected.items():
    f=base/"OwnerBridge/app"/rel
    if f.is_symlink() or not f.is_file() or f.stat().st_size>1048576:
        result[rel]={"status":"U"};continue
    raw=f.read_bytes()
    try:
        actual=raw.decode("utf-8-sig").replace("\r\n","\n")
        target=src.replace("\r\n","\n")
        aa,bb=ast.parse(actual),ast.parse(target)
        if actual==target:status="T"
        elif ast.dump(aa,include_attributes=False)==ast.dump(bb,include_attributes=False):status="A"
        elif stripped(aa)==stripped(bb):status="S"
        else:status="D"
        result[rel]={"status":status,"sha256":hashlib.sha256(raw).hexdigest(),"blob":hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()}
    except (UnicodeError,SyntaxError,ValueError):
        result[rel]={"status":"U"}
(report/"comparison.json").write_text(json.dumps(result,sort_keys=True),encoding="utf-8")
print("V13_AST_G"+result["poc/p2-aisub/run_assumed_source_gateway.py"]["status"]+"P"+result["poc/p3-vietsub-trigger/activation_gate.py"]["status"])
'@
$file=Join-Path $report 'compare.py'
[IO.File]::WriteAllText($file,$py,[Text.UTF8Encoding]::new($false))
$lines=@(& py -3 -I -B $file $base $report 2> (Join-Path $report 'stderr.txt'))
$code='V13_AST_PRIVATE_ERROR'
if($LASTEXITCODE -eq 0 -and $lines.Count -eq 1 -and [string]$lines[0] -cmatch '^V13_AST_G[TASDU]P[TASDU]$'){$code=[string]$lines[0]}
$doc=@{schema='TTV-ODYSSEY-STAGE-V1';nonce=$rq.nonce;reason=$code}
[IO.File]::WriteAllText((Join-Path $spool ('Receipts\odyssey-stage-'+$rq.nonce+'.json')),($doc|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false))
Write-Output $code
